// flags and description only (the names and defaults are CsqcEngineCvars). Generated; see the class comment.
namespace VortexArena.Legacy.Menu;

/// <summary>
/// What DarkPlaces knows about its own console variables besides their defaults: which are saved to
/// config.cfg (CF_ARCHIVE), which cannot be changed (CF_READONLY), which are hidden from QuakeC
/// (CF_PRIVATE), and the one-line description each was declared with.
///
/// The menu program is the thing that needs these. Its settings dialogs read cvar_type to decide whether a
/// cvar is the engine's and whether it is saved, its "advanced settings" list prints cvar_description for
/// every cvar there is, and what the player changes there has to reach config.cfg the way Host_SaveConfig
/// writes it - which depends on the archive flag, not on anything the menu does.
///
/// Generated by a regular expression over the C sources (the same pass that produced CsqcEngineCvars).
/// Flags: 1 archive, 2 read-only, 4 private. Descriptions are the C string literals, unchanged.
/// </summary>
public static class MenuEngineCvarInfo
{
    public const int Archive = 1, ReadOnly = 2, Private = 4;

    // Built on first use: a static initialiser here would run before Table, which is declared below it.
    private static Dictionary<string, (int Flags, string Description)>? s_byName;
    private static Dictionary<string, (int Flags, string Description)> ByName => s_byName ??= Build();

    private static Dictionary<string, (int, string)> Build()
    {
        Dictionary<string, (int, string)> map = new(Table.Length, StringComparer.Ordinal);
        foreach ((string name, int flags, string description) in Table) map[name] = (flags, description);
        return map;
    }

    /// <summary>True for a cvar the engine itself declares (as opposed to one a configuration file or a program created).</summary>
    public static bool IsEngineCvar(string name) => ByName.ContainsKey(name);

    /// <summary>The engine's flags for a cvar (<see cref="Archive"/>, <see cref="ReadOnly"/>, <see cref="Private"/>), 0 if it is not the engine's.</summary>
    public static int Flags(string name) => ByName.TryGetValue(name, out (int Flags, string Description) entry) ? entry.Flags : 0;

    /// <summary>The engine's description of a cvar, "" if it has none or is not the engine's.</summary>
    public static string Description(string name) => ByName.TryGetValue(name, out (int Flags, string Description) entry) ? entry.Description : "";

