        ("sv_autodemo_perclient_discardable", 1, "Allow game code to decide whether a demo should be kept or discarded."),
        ("sv_autodemo_perclient_nameformat", 1, "The format of the sv_autodemo_perclient filename, followed by the map name, the client number and the IP address + port number, separated by underscores (the date is encoded using strftime escapes)"),
        ("sv_cheats", 0, "enables cheat commands in any game, and cheat impulses in dpmod"),
        ("sv_checkforpacketsduringsleep", 0, "uses select() function to wait between frames which can be interrupted by packets being received, instead of Sleep()/usleep()/SDL_Sleep() functions which do not check for packets"),
        ("sv_clmovement_enable", 0, "whether to allow clients to use cl_movement prediction, which can cause choppy movement on the server which may annoy other players"),
        ("sv_clmovement_inputtimeout", 0, "when a client does not send input for this many seconds (max 0.1), force them to move anyway (unlike QuakeWorld)"),
        ("sv_clmovement_minping", 0, "if client ping is below this time in milliseconds, then their ability to use cl_movement prediction is disabled for a while (as they don't need it)"),
        ("sv_clmovement_minping_disabletime", 0, "when client falls below minping, disable their prediction for this many milliseconds (should be at least 1000 or else their prediction may turn on/off frequently)"),
        ("sv_cullentities_nevercullbmodels", 0, "if enabled the clients are always notified of moving doors and lifts and other submodels of world (warning: eats a lot of network bandwidth on some levels!)"),
        ("sv_cullentities_pvs", 0, "fast but loose culling of hidden entities"),
        ("sv_cullentities_stats", 0, "displays stats on network entities culled by various methods for each client"),
        ("sv_cullentities_trace", 0, "somewhat slow but very tight culling of hidden entities, minimizes network traffic and makes wallhack cheats useless"),
        ("sv_cullentities_trace_delay", 0, "number of seconds until the entity gets actually culled (also applies to portal camera eyes even if sv_cullentities_trace is 0)"),
        ("sv_cullentities_trace_delay_players", 0, "number of seconds until the entity gets actually culled if it is a player entity"),
        ("sv_cullentities_trace_enlarge", 0, "box enlargement for entity culling (also applies to portal camera eyes even if sv_cullentities_trace is 0)"),
        ("sv_cullentities_trace_entityocclusion", 0, "also check if doors and other bsp models are in the way"),
        ("sv_cullentities_trace_expand", 0, "box is expanded by this many units for entity culling (also applies to portal camera eyes even if sv_cullentities_trace is 0)"),
        ("sv_cullentities_trace_eyejitter", 0, "jitter the eye by this much for each trace (also applies to portal camera eyes even if sv_cullentities_trace is 0)"),
        ("sv_cullentities_trace_prediction", 0, "also trace from the predicted player position"),
        ("sv_cullentities_trace_prediction_time", 0, "maximum ping time to predict in seconds"),
        ("sv_cullentities_trace_samples", 0, "number of samples to test for entity culling"),
        ("sv_cullentities_trace_samples_extra", 0, "number of samples to test for entity culling when the entity affects its surroundings by e.g. dlight (also applies to portal camera eyes even if sv_cullentities_trace is 0)"),
        ("sv_cullentities_trace_samples_players", 0, "number of samples to test for entity culling when the entity is a player entity"),
        ("sv_cullentities_trace_spectators", 0, "enables trace entity culling for clients that are spectating"),
        ("sv_curl_defaulturl", 0, "default autodownload source URL"),
        ("sv_curl_maxspeed", 0, "maximum download speed for clients downloading from sv_curl_defaulturl (KiB/s)"),
        ("sv_curl_serverpackages", 0, "list of required files for the clients, separated by spaces"),
        ("sv_debugmove", 0, "disables collision detection optimizations for debugging purposes"),
        ("sv_dedicated", 2, "for scripts and SVQC to detect when they're running on a dedicated server"),
        ("sv_disablenotify", 0, "suppress broadcast prints when certain cvars are changed (CF_NOTIFY flag in engine code)"),
        ("sv_echobprint", 1, "prints gamecode bprint() calls to server console"),
        ("sv_entfields_noescapes", 0, "Space-separated list of fields in which backslashes won't be parsed as escapes when loading entities from .bsp or .ent files. This is a workaround for buggy maps with unescaped backslashes used as path separators (only forward slashes are allowed in Quake VFS paths)."),
        ("sv_entpatch", 0, "enables loading of .ent files to override entities in the bsp (for example Threewave CTF server pack contains .ent patch files enabling play of CTF on id1 maps)"),
        ("sv_freezenonclients", 0, "freezes time, except for players, allowing you to walk around and take screenshots of explosions"),
        ("sv_friction", 0, "how fast you slow down"),
        ("sv_gameplayfix_blowupfallenzombies", 0, "causes findradius to detect SOLID_NOT entities such as zombies and corpses on the floor, allowing splash damage to apply to them"),
        ("sv_gameplayfix_consistentplayerprethink", 0, "improves fairness in multiplayer by running all PlayerPreThink functions (which fire weapons) before performing physics, then running all PlayerPostThink functions"),
        ("sv_gameplayfix_delayprojectiles", 0, "causes entities to not move on the same frame they are spawned, meaning that projectiles wait until the next frame to perform their first move, giving proper interpolation and rocket trails, but making weapons harder to use at low framerates"),
        ("sv_gameplayfix_downtracesupportsongroundflag", 0, "prevents very short moves from clearing onground (which may make the player stick to the floor at high netfps), fixes groundentity not being set when walking onto a mover with sv_gameplayfix_nogravityonground"),
        ("sv_gameplayfix_droptofloorstartsolid", 0, "prevents items and monsters that start in a solid area from falling out of the level (makes droptofloor treat trace_startsolid as an acceptable outcome)"),
        ("sv_gameplayfix_droptofloorstartsolid_nudgetocorrect", 0, "tries to nudge stuck items and monsters out of walls before droptofloor is performed"),
        ("sv_gameplayfix_easierwaterjump", 0, "changes water jumping to make it easier to get out of water (exactly like in QuakeWorld)"),
        ("sv_gameplayfix_findradiusdistancetobox", 0, "causes findradius to check the distance to the corner of a box rather than the center of the box, makes findradius detect bmodels such as very large doors that would otherwise be unaffected by splash damage"),
        ("sv_gameplayfix_fixedcheckwatertransition", 0, "fix two very stupid bugs in SV_CheckWaterTransition when watertype is CONTENTS_EMPTY (the bugs causes waterlevel to be 1 on first frame, -1 on second frame - the fix makes it 0 on both frames)"),
        ("sv_gameplayfix_gravityunaffectedbyticrate", 0, "fix some ticrate issues in physics."),
        ("sv_gameplayfix_grenadebouncedownslopes", 0, "prevents MOVETYPE_BOUNCE (grenades) from getting stuck when fired down a downward sloping surface"),
        ("sv_gameplayfix_impactbeforeonground", 0, "enables a bug from old DP versions in which entity .touch functions are called before FL_ONGROUND is set when a collision is detected in SV_FlyMove() (used by MOVETYPE_WALK and MOVETYPE_STEP), Quake 1.5 and Combat+ mods require this, it breaks id1 fiends"),
        ("sv_gameplayfix_multiplethinksperframe", 0, "allows entities to think more often than the server framerate, primarily useful for very high fire rate weapons"),
        ("sv_gameplayfix_noairborncorpse", 0, "causes entities (corpses, items, etc) sitting ontop of moving entities (players) to fall when the moving entity (player) is no longer supporting them"),
        ("sv_gameplayfix_noairborncorpse_allowsuspendeditems", 0, "causes entities sitting ontop of objects that are instantaneously remove to float in midair (special hack to allow a common level design trick for floating items)"),
        ("sv_gameplayfix_nogravityonground", 0, "turn off gravity when on ground (to get rid of sliding)"),
        ("sv_gameplayfix_nosquashentities", 0, "Entity hitboxes will not be resized or disabled when they are crushed by movers, and will continue to be affected by movers."),
        ("sv_gameplayfix_nostepmoveonsteepslopes", 0, "crude fix which prevents MOVETYPE_STEP (not swimming or flying) to move on slopes whose angle is bigger than 45 degree"),
        ("sv_gameplayfix_nudgeoutofsolid", 0, "attempts to fix physics errors where an object ended up in solid for some reason, smarter than sv_gameplayfix_unstick* except on Q1BSP with mod_q1bsp_polygoncollisions disabled (there it falls back to the unsticking method)"),
        ("sv_gameplayfix_nudgeoutofsolid_separation", 0, "keep objects this distance apart to prevent collision issues on seams"),
        ("sv_gameplayfix_q1bsptracelinereportstexture", 0, "enables mods to get accurate trace_texture results on q1bsp by using a surface-hitting traceline implementation rather than the standard solidbsp method, q3bsp always reports texture accurately"),
        ("sv_gameplayfix_q2airaccelerate", 0, "Quake2-style air acceleration"),
        ("sv_gameplayfix_setmodelrealbox", 0, "fixes a bug in Quake that made setmodel always set the entity box to ('-16 -16 -16', '16 16 16') rather than properly checking the model box, breaks some poorly coded mods"),
        ("sv_gameplayfix_slidemoveprojectiles", 0, "allows MOVETYPE_FLY/FLYMISSILE/TOSS/BOUNCE/BOUNCEMISSILE entities to finish their move in a frame even if they hit something, fixes 'gravity accumulation' bug for grenades on steep slopes"),
        ("sv_gameplayfix_stepdown", 0, "attempts to step down stairs, not just up them (prevents the familiar thud..thud..thud.. when running down stairs and slopes)"),
        ("sv_gameplayfix_stepmultipletimes", 0, "applies step-up onto a ledge more than once in a single frame, when running quickly up stairs"),
        ("sv_gameplayfix_swiminbmodels", 0, "causes pointcontents (used to determine if you are in a liquid) to check bmodel entities as well as the world model, so you can swim around in (possibly moving) water bmodel entities"),
        ("sv_gameplayfix_unstickentities", 0, "hack to check if entities are crossing world collision hull and try to move them to the right position. Quake didn't do this so maps shouldn't depend on it."),
        ("sv_gameplayfix_unstickplayers", 0, "big hack to try and fix the rare case of MOVETYPE_WALK entities getting stuck in the world clipping hull. Quake did something similar."),
        ("sv_gameplayfix_upwardvelocityclearsongroundflag", 0, "prevents monsters, items, and most other objects from being stuck to the floor when pushed around by damage, and other situations in mods"),
        ("sv_gravity", 0, "how fast you fall (512 = roughly earth gravity)"),
